import React from 'react';

export default function IndianPlayers() {
  const IndianTeam = ['Sachin1', 'Dhoni2', 'Virat3', 'Rohit4', 'Yuvaraj5', 'Raina6'];

  // Destructuring odd players
  const [first, , third, , fifth] = IndianTeam;
  // Destructuring even players
  const [, second, , fourth, , sixth] = IndianTeam;

  // Merge arrays using spread
  const T20Players = ['First Player', 'Second Player', 'Third Player'];
  const RanjiPlayers = ['Fourth Player', 'Fifth Player', 'Sixth Player'];
  const mergedPlayers = [...T20Players, ...RanjiPlayers];

  return (
    <div>
      <h1>Odd Players</h1>
      <ul>
        <li>First : {first}</li>
        <li>Third : {third}</li>
        <li>Fifth : {fifth}</li>
      </ul>
      <hr />
      <h1>Even Players</h1>
      <ul>
        <li>Second : {second}</li>
        <li>Fourth : {fourth}</li>
        <li>Sixth : {sixth}</li>
      </ul>
      <hr />
      <h1>List of Indian Players Merged:</h1>
      <ul>
        {mergedPlayers.map((player, i) => (
          <li key={i}>Mr. {player}</li>
        ))}
      </ul>
    </div>
  );
}
